import json
import os
import subprocess
import tempfile

# Lambda handler for Step Functions workflow
# Processes document conversion tasks from state machine input

def validate_input_type(event):
    """Validate the task input from Step Functions state machine."""
    task_type = event.get('taskType')
    payload = event.get('payload')

    # Type checking for workflow routing
    if not isinstance(task_type, str):
        raise ValueError(f"taskType must be string, got {type(task_type)}")

    return task_type, payload


def process_document(payload):
    """Process document based on payload configuration."""
    # payload.source can be a string path or a dict with nested config
    source = payload.get('source')
    output_dir = payload.get('outputDir', '/tmp/output')

    # Type confusion: source is expected to be a string file path
    # but Step Functions JSON allows passing arbitrary nested objects
    # If source is a dict with __class__ or special keys, behavior changes
    if hasattr(source, 'keys'):
        # Dict-like source treated as "advanced config"
        file_path = source.get('path', '')
        transform_cmd = source.get('transform', 'cat')
    else:
        file_path = str(source)
        transform_cmd = 'cat'

    # Ensure output directory exists
    os.makedirs(output_dir, exist_ok=True)

    output_file = os.path.join(output_dir, 'result.txt')

    # VULNERABILITY: transform_cmd from untrusted input used in shell command
    # Type confusion allows attacker to inject via dict-type source
    cmd = f"{transform_cmd} {file_path} > {output_file}"

    result = subprocess.run(
        cmd,
        shell=True,
        capture_output=True,
        text=True,
        timeout=30
    )

    if result.returncode != 0:
        return {'status': 'error', 'stderr': result.stderr}

    # Read output
    with open(output_file, 'r') as f:
        content = f.read()

    return {'status': 'success', 'content': content[:1024]}


def read_sensitive_config():
    """Read workflow configuration from mounted secrets."""
    config_path = os.environ.get('CONFIG_PATH', '/etc/app/config.json')
    try:
        with open(config_path, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def handler(event, context):
    """Main Step Functions task handler."""
    try:
        task_type, payload = validate_input_type(event)

        if task_type == 'document_convert':
            if not isinstance(payload, dict):
                return {'statusCode': 400, 'body': 'payload must be object'}
            result = process_document(payload)
        elif task_type == 'config_read':
            result = read_sensitive_config()
        else:
            return {'statusCode': 400, 'body': f'Unknown taskType: {task_type}'}

        return {
            'statusCode': 200,
            'body': json.dumps(result),
            'taskToken': event.get('taskToken')
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }


if __name__ == '__main__':
    # Local testing
